using System;using System.Collections.Generic;using System.Drawing;using System.Linq;using System.Text;
namespace DoomSNESed {
    public static class CopyrightAssets {
        public const int Id=6,Table=0x1ff603;
        static int Root(byte[] rom){return RomLayout.At(rom,Table);}
        static char Display(byte value){return value==127?'©':value==128?'®':value==129?'™':(char)value;}
        public static byte[] Encode(string text){return (text??"").Select(c=>c=='©'?(byte)127:c=='®'?(byte)128:c=='™'?(byte)129:c>=32&&c<=126?(byte)c:ThrowCharacter()).ToArray();}
        static byte ThrowCharacter(){throw new System.IO.InvalidDataException("Use the game's font: ASCII text, ©, ® or ™.");}
        public static List<CreditLine> Read(byte[] rom){var result=new List<CreditLine>();int root=Root(rom);for(int i=0;i<64;i++){int p=root+i*6,dest=Bin.U16(rom,p);if(dest==65535)return result;Bin.Require(dest>=0x2000&&dest<0x2380,"Invalid copyright text layout.");int start=GraphicsAssets.Address(rom,p+2),n=rom[p+5];Bin.Require(start>=0&&start+n<=rom.Length,"Invalid copyright text pointer.");result.Add(new CreditLine{Record=i,Column=(dest-0x2000)%32,Row=(dest-0x2000)/32,Text=new string(rom.Skip(start).Take(n).Select(Display).ToArray())});}throw new System.IO.InvalidDataException("Copyright text table is not terminated.");}
        public static void Validate(CreditLine line){Bin.Require(line.Row>=0&&line.Row<28&&line.Column>=0&&line.Column<32,"Copyright layout uses rows 0..27 and columns 0..31.");Bin.Require(Encode(line.Text).Length<=32-line.Column,"Copyright text must fit within 32 columns.");}
        public static void Apply(Rom rom,byte[] target,TextReplacement replacement,List<Section> free,ref int used){var original=Read(rom.Bytes);Bin.Require(replacement.Lines!=null&&replacement.Lines.Count==original.Count&&replacement.Lines.Select(l=>l.Record).OrderBy(i=>i).SequenceEqual(original.Select(l=>l.Record)),"Keep the copyright's native entry count; leave text empty to hide a row.");foreach(var line in replacement.Lines){Validate(line);var prior=original.Single(l=>l.Record==line.Record);int p=Root(target)+line.Record*6;Bin.W16(target,p,0x2000+line.Row*32+line.Column);if(line.Text==prior.Text)continue;byte[] bytes=Encode(line.Text);if(bytes.Length==0)bytes=new byte[]{32};int address=GraphicsAssets.Store(target,bytes,free,ref used);Bin.W16(target,p+2,address);target[p+4]=GraphicsAssets.CpuBank(address);target[p+5]=(byte)bytes.Length;}}
        public static Bitmap Preview(Rom rom,TextReplacement replacement,List<GraphicReplacement> graphics){var bitmap=new Bitmap(256,224);using(var g=Graphics.FromImage(bitmap))g.Clear(Color.Black);var change=graphics.FirstOrDefault(a=>a.Screen==6);byte[] font=change==null?HudAssets.Data(rom.Bytes,6):HudAssets.Tiles(change,rom.Bytes);foreach(var line in replacement==null?Read(rom.Bytes):replacement.Lines){byte[] text=Encode(line.Text);for(int c=0;c<text.Length;c++){int tile=text[c]-32;if(tile<0||tile*32+31>=font.Length)continue;for(int y=0;y<8;y++)for(int x=0;x<8;x++){int index=0;for(int plane=0;plane<4;plane++)index|=((font[tile*32+plane/2*16+y*2+plane%2]>>(7-x))&1)<<plane;int dx=(line.Column+c)*8+x,dy=line.Row*8+y;if(index!=0&&dx>=0&&dx<256&&dy>=0&&dy<224)bitmap.SetPixel(dx,dy,index==7?Color.FromArgb(57,0,0):index==11?Color.Red:Color.Black);}}}return bitmap;}
    }
}
